body_md:
A non-negative measurable map $E:\Omega \to [0,\infty]$ is called an \emph{\textsc{e}-variable for $H_0$} if:
    \begin{align}
        \mathbb{E}_{P_0}[E] \le 1.
    \end{align}

Let $E:\Omega \to [0,\infty]$ be an \textsc{e}-variable for $H_0$. Then its \emph{\textsc{e}-power} for $H_1$ is given by:
    \begin{align}
       \mathbb{E}_{P_1}[\log E].
    \end{align}

\label{lem:neyman-pearson-e-power}
    Under the assumption of absolute continuity: $P_1 \ll P_0$,
     the $P_0$-essentially unique \textsc{e}-variable for $H_0$ with maximal \textsc{e}-power for $H_1$ is given by the likelihood-ratio, i.e.\ the Radon-Nikodym derivative:
    \begin{align}
        E^*(x) &:= \frac{dP_1}{dP_0}(x),
    \end{align}
    which has the \textsc{e}-power:
    \begin{align}
          \mathbb{E}_{P_1}[\log E^*] \overset{!}{=} \operatorname{KL}(P_1\|P_0),
    \end{align}
    the Kullback-Leibler divergence between $P_1$ and $P_0$.

Let $\mathcal{F} \subseteq \mathcal{B}$ be a sub-$\sigma$-algebra of $\mathcal{B}$\footnote{A sub-$\sigma$-algebra $\mathcal{F} \subseteq \mathcal{B}$ is typically of the form $\mathcal{F}=\sigma(Z_1,\dots,Z_t)$ for some random variables $Z_1,\dots,Z_t: \Omega \to \mathcal{Z}$. So, $\mathcal{F}$ then encodes the information of the outcomes of $Z_1,\dots,Z_t$.} on $\Omega$. 
    A non-negative measurable map $E:\Omega \to [0,\infty]$ is called a \emph{conditional \textsc{e}-variable for $H_0$ conditional on $\mathcal{F}$} if:
    \begin{align}
        \mathbb{E}_{P_0}[E|\mathcal{F}] \le 1 \qquad P_0\text{-a.s.}
    \end{align}
    Its \emph{conditional \textsc{e}-power} for $H_1$ conditional on $\mathcal{F}$ is defined by:
    \begin{align}
        \mathbb{E}_{P_1}[\log E|\mathcal{F}].
    \end{align}

\label{not:main}
   Let $(E_t)_{t \in \mathbb{N}_0}$ be a sequence of conditional \textsc{e}-variables for $H_0$, $E_t: \Omega \to [0,\infty]$, $E_0:=1$, adapted to the filtration $\mathcal{F}=(\mathcal{F}_t)_{t \in \mathbb{N}_0}$ of sub-$\sigma$-algebras $\mathcal{F}_t \subseteq \mathcal{B}$:
   \begin{align}
       \mathcal{F}_0 \subseteq \mathcal{F}_1 \subseteq \mathcal{F}_2 \subseteq \cdots \subseteq \mathcal{F}_t \subseteq \cdots \subseteq \mathcal{B},
   \end{align}
   each conditional on its own past, that is, for every $t \in \mathbb{N}_1$ the map $E_t: \Omega \to [0,\infty]$ is $\mathcal{F}_t$-measurable and:
    \begin{align}
        \mathbb{E}_{P_0}[E_t|\mathcal{F}_{t-1}] \le 1 \qquad P_0\text{-a.s.}
    \end{align}
    We further construct non-negative variables $W_t:\Omega \to [0,\infty]$ as follows for $t \in \mathbb{N}_1$ by multiplication:
    \begin{align}
         W_t &:= E_t \cdot W_{t-1} = E_t \cdot E_{t-1}\cdots E_1, & W_0 &:= 1.
    \end{align}

With the \Cref{not:main}, each $W_t$ for $t \ge 0$ is an (unconditional) \textsc{e}-variable for $H_0$ and the sequence $(W_t)_{t \in \mathbb{N}_0}$ is a non-negative supermartingale adapted to the filtration $\mathcal{F}=(\mathcal{F}_t)_{t \in \mathbb{N}_0}$ w.r.t.\ $P_0$. More concretely, for $t \in \mathbb{N}_1$ we have:
    \begin{align}
        \mathbb{E}_{P_0}[W_t|\mathcal{F}_{t-1}] &\le W_{t-1} \qquad P_0\text{-a.s.}, &  \mathbb{E}_{P_0}[W_0]&=1.
    \end{align}

\label{thm:type-I-error}
    With the \Cref{not:main}, we have the following upper bound on the \emph{anytime-valid type-I error} for the above sequential test for every $\alpha \in (0,1]$:
    \begin{align}
        P_0\left (  \exists t \in \mathbb{N}_0.\; W_t > \frac{1}{\alpha} \right )  = P_0\left (  \sup_{t \in \mathbb{N}_0} W_t > \frac{1}{\alpha} \right )   \overset{!}{\le} \alpha.
    \end{align}

\label{thm:type-II-error}
With the \Cref{not:main}, assume that for every $t \in \mathbb{N}_1$ there are constants $a_t, b_t, c_t \in \mathbb{R}$ such that:
\begin{align}
    a_t &\le \log E_t \le b_t \quad P_1\text{-a.s.}, & 
    c_t & \le \mathbb{E}_{P_1}[\log E_t|\mathcal{F}_{t-1}]
    \quad P_1\text{-a.s.}.
\end{align}
Then for every $\alpha \in (0,1]$ and $t \in \mathbb{N}_1$ we have the following type-II error bound\footnote{For $s \in \mathbb{R}$ we put $s_+:=\max(0,s)$ and $s_+^2:=(s_+)^2$.}:
\begin{align}
P_1\left (  W_t\le \frac{1}{\alpha} \right )  & 
    \le \exp\left (  - \frac{2\left (  \sum_{n=1}^t c_n - \log \frac{1}{\alpha}\right ) _+^2}{\sum_{n=1}^t (b_n-a_n)^2} \right ) .
\end{align}
In particular, if the bounds are the same ($a_t=a$, $b_t=b$, $c_t=c$) for all $t \in \mathbb{N}_1$ with positive (conditional) \textsc{e}-power lower bound $c >0$ for $H_1$ then the \emph{type-II error} bound simplifies and converges to zero with asymptotically \emph{geometric rate}:
\begin{align}
    P_1\left (  W_t\le \frac{1}{\alpha} \right )  & 
    \le \exp\left (  - 2t \cdot \frac{\left (  c - \frac{1}{t}\log \frac{1}{\alpha}\right ) _+^2}{(b-a)^2} \right )  \overset{t \to \infty}{\longrightarrow} 0.
\end{align} 
As a consequence, we then have \emph{asymptotic power one}:
\begin{align}
   P_1\left (  \sup_{t \in \mathbb{N}_0} W_t > \frac{1}{\alpha} \right )  = P_1\left (  \sup_{t \in \mathbb{N}_0} W_t = \infty \right )  & = 1.
\end{align}

\label{rem:clipping}
    If $E$ is an \textsc{e}-variable for $H_0$, but for which $\log E$ might not be bounded, then for every $\gamma \in (0,1]$ we can introduce its \emph{$\gamma$-clipped} version:
    \begin{align}
        E_\gamma(x) &:= \gamma + (1-\gamma) \cdot \min(E(x),\gamma^{-1}) \le 1 + E(x),
    \end{align}
    which is again an \textsc{e}-variable for $H_0$ and for which we then have the bounds: 
    \begin{align}
        - \log \frac{1}{\gamma} \le \log E_\gamma(x) \le \log \frac{1}{\gamma},
    \end{align}
    together with the pointwise convergence:
    \begin{align}
        \lim_{\gamma \to 0} E_\gamma(x) &= E(x),
    \end{align}
    which is monotone non-decreasing if $E(x)\ge 1$ and monotone non-increasing if $E(x) \le 1$ for $\gamma \to 0$.
    This then implies the following convergences of the integrals for arbitrary measures $P$:
    \begin{align}
        \lim_{\gamma \to 0} \int E_\gamma\, dP &= \int E\, dP, & \lim_{\gamma \to 0} \int \log E_\gamma\, dP &= \int \log E\, dP.
    \end{align}
    The latter limit holds, whenever the integral on the right is well-defined (possibly $\pm \infty$, but excluding the $\infty - \infty$ case). The convergence of the integrals can be shown with help of the monotone convergence theorem, applied on the sets $\left \{  E \le 1 \right \} $ and $\left \{  E > 1 \right \} $ separately.

    This allows us to take an \textsc{e}-variable $E$ for $H_0$ with positive \textsc{e}-power $\mathbb{E}_{P_1}[\log E] > 0$ for $H_1$ (but with possible unbounded $\log E$), and clip it with some small $\gamma > 0$. If $\gamma >0$ is sufficiently small then also $E_\gamma$ will have positive \textsc{e}-power $\mathbb{E}_{P_1}[\log E_\gamma] >0$ for $H_1$ and, in addition, the geometrically decaying type-II error bounds of \Cref{thm:type-II-error} will hold with the bounds $a:= - \log \frac{1}{\gamma}$, $b:=\log \frac{1}{\gamma}$ and $c:=\mathbb{E}_{P_1}[\log E_\gamma] >0$.

\label{rem:rejection-time}
    With the \Cref{not:main}, we introduce the \emph{rejection time} of the test supermartingale $(W_t)_{t \in \mathbb{N}}$ w.r.t.\ $\alpha \in (0,1]$:
    \begin{align}
        \tau_\alpha &:= \inf \left \{  t \in \mathbb{N}_0 \,\middle|\, W_t > \frac{1}{\alpha} \right \} .
    \end{align}
    To get an intuition about the average rejection time, assume, for simplicity, that $(x_t)_{t \in \mathbb{N}} \sim P_1$ is i.i.d.\ and that we use the same \textsc{e}-variable at each time: $E_t = E(x_t)$ for $t \in \mathbb{N}$. 
    Via Wald's equation, under integrability conditions\footnote{The minimal assumptions for the validity of Wald's equation are: $\mathbb{E}_{P_1}[(\log E)_-] < \infty$ and $\mathbb{E}_{P_1}[\log E] > 0$.}, see \cite{Wald44, Dur19}, we then get the following close approximation for the \emph{average rejection time}:
    \begin{align}
        \mathbb{E}_{P_1}[\tau_\alpha] = \frac{\mathbb{E}_{P_1}\left [  \log W_{\tau_\alpha}\right ] }{\mathbb{E}_{P_1}[\log E]} &  \;\gtrapprox\; \frac{\log \frac{1}{\alpha}}{\mathbb{E}_{P_1}[\log E]},
    \end{align}
    which can be interpreted as the average number of samples needed to obtain a rejection. 
    The above formula shows that, if we want to minimize the average rejection time, we need to maximize the \textsc{e}-power of $E$, which by \Cref{lem:neyman-pearson-e-power} is uniquely maximized by the likelihood ratio: $E^*=\frac{dP_1}{dP_0}$, for which we then get the minimal average rejection time:
       \begin{align}
        \mathbb{E}_{P_1}[\tau^*_\alpha] & \;\gtrapprox\; \frac{\log \frac{1}{\alpha}}{\operatorname{KL}(P_1\|P_0)}.
    \end{align}

Let $K\ge 1$ and $h:\Omega \to [0,\infty)$ be any map for which $0 < h(Z^1) + \sum_{k=1}^{K} h(Z^0_k) < \infty$ $\mathbb{P}_1$-almost-surely, then the map $E^{(K,h)}$ given by:
\begin{align}
    E^{(K,h)}(z^1,z^0_1,\dots, z^0_K) &:= \frac{h(z^1)}{\frac{1}{K+1}\left (  h(z^1)+\sum_{k=1}^K h(z^0_k)\right ) },
\end{align}    
    is a valid \textsc{e}-variable for $H_0$ with:
\begin{align}
   E^{(K,h)} &\ge 0, & \mathbb{E}_{\mathbb{P}_0}\left [  E^{(K,h)} \right ]  &= 1.
\end{align}

\label{prp:optimal-e-power-k}
    Let $P_0$, $P_1$ be two probability distributions on $\Omega$ with $P_1 \ll P_0$ and $K \ge 1$ be a fixed natural number. 
    Then consider all measurable functions $h: \Omega \to [0,\infty)$ for which $0 < h(Z^1) + \sum_{k=1}^{K} h(Z^0_k) < \infty$ $\mathbb{P}_1$-almost-surely, and, the following \textsc{e}-power objective:
    \begin{align}
        J_K(h) &:= \mathbb{E}_{\mathbb{P}_1}\left [  \log E^{(K,h)} \right ] .
    \end{align}
    Then each maximizer $h^*$ of $J_K$ is $P_0$-almost-surely of the form:
    \begin{align}
         h^*(z) &= c \cdot \frac{dP_1}{dP_0}(z),
    \end{align}
    for some constant $c \in \mathbb{R}_{>0}$. Conversely, those functions maximize $J_K$ (for all $K \ge 1$ simultaneously).  The optimal \textsc{e}-variable of our given type is thus given by:
    \begin{align}
        E^{(K,*)}(z^1,z^0_1,\dots,z^0_K) 
        &:= \frac{ \frac{dP_1}{dP_0}(z^1)}{\frac{1}{K+1}\left (  \frac{dP_1}{dP_0}(z^1) + \sum_{k=1}^K \frac{dP_1}{dP_0}(z^0_k)\right ) } 
        \quad \underset{\text{a.s.}}{\overset{K \to \infty}{\longrightarrow}} \quad \frac{dP_1}{dP_0}(z^1) =: E^*(z^1),
    \end{align}
which (for each fixed $z^1$) converges $P_0^{\otimes \mathbb{N}_1}$-almost-surely to the overall most \textsc{e}-powerful \textsc{e}-variable $E^*(z^1)=\frac{dP_1}{dP_0}(z^1)$ for $H_0$ vs.\ $H_1$, see \Cref{lem:neyman-pearson-e-power}, for $K \to \infty$. 
Furthermore, for the \textsc{e}-power of $E^{(K,*)}$ we have the following Jensen inequality:
\begin{align}
    \operatorname{KL}(P_1\|P_0)  \quad \ge \quad  \mathbb{E}_{\mathbb{P}_1}[\log E^{(K,*)}] \quad\overset{!}{\ge}\quad \operatorname{KL}(P_1\|P_0) - \log\left (  1 + \frac{\chi^2(P_1\|P_0)}{K+1} \right )  \quad \overset{K \to \infty}{\longrightarrow} \quad\operatorname{KL}(P_1\|P_0),
\end{align}
provided $\chi^2(P_1\|P_0) < \infty$.
If, even more, $\frac{dP_1}{dP_0}$ is bounded, then we have the \emph{uniform} (in $z^1$) $P_0^{\otimes \mathbb{N}_1}$-almost-sure convergence:
\begin{align}
   \sup_{z^1 \in \Omega} \left|  \log E^{(K,*)}(z^1,z^0_1,\dots,z^0_K) - \log E^*(z^1) \right|  \quad \underset{\text{a.s.}}{\overset{K \to \infty}{\longrightarrow}} \quad 0.
\end{align}

\label{not:empirical-e-val}
To approximate the most \textsc{e}-powerful \textsc{e}-variable for $H_0$ vs.\ $H_1$, we make use of a flexible, optimizable paramterized function class $g_\theta: \Omega \to \mathbb{R}$, for example, deep neural networks of some architecture, with parameters $\theta \in \Theta$. 
We then put $h_\theta(z) := \exp(g_\theta(z))$ to use inside $E^{(K,h)}$ and get the parameterized \textsc{e}-variables for $H_0$:
\begin{align}
    E^{(K,\theta)}(z^1,z^0_1,\dots,z^0_K) &:= \frac{ \exp(g_\theta(z^1))}{\frac{1}{K+1}\left (  \exp(g_\theta(z^1)) + \sum_{k=1}^K \exp(g_\theta(z^0_k)) \right )  }. \label{eq:e-var-ratio}
\end{align}

We will optimize the \textsc{e}-power of $E^{(K,\theta)}$ by using an empirical estimate of the \textsc{e}-power objective $J_K$ from above, using i.i.d.\ samples from $P_0$ and $P_1$.
For this first sample sufficiently many:
\begin{align}
    (z^1_n)_{n \in [N]} &\overset{\text{i.i.d.}}{\sim} P_1, & (z^0_{n,k})_{\substack{n \in [N]\\ k \in [K]}} &\overset{\text{i.i.d.}}{\sim} P_0.
\end{align}
We then consider the empirical objective:
\begin{align}
    J_{K,N}(\theta) &:= \frac{1}{N}\sum_{n=1}^N \log E^{(K,\theta)}\left (  z^1_n,(z^0_{n,k})_{k \in [K]} \right ) .
\end{align}
We then maximize this objective to receive the following estimator:
\begin{align}
     \hat \theta_{K,N} &: \in \operatorname*{argmax}_{\theta \in \Theta}  J_{K,N}(\theta),
\end{align}
or, more generally, a sequence of \emph{near-maximizing estimators} $(\hat \theta_{K,N})_{N \in \mathbb{N}_1}$ that might come with some \emph{optimization gap} $(\hat \xi_{K,N})_{N \in \mathbb{N}_1}$, e.g.\ a gradient optimizer stuck in a local, non-global, maximum, etc., satisfying:
\begin{align}
     J_{K,N}(\hat \theta_{K,N}) &\ge  \sup_{\theta \in \Theta}  J_{K,N}(\theta) - \xi_{K,N}, & \xi_K &:= \limsup_{N \to \infty} \xi_{K,N} \in \mathbb{R}_{\ge 0}.
\end{align}
The resulting \textsc{e}-variable for $H_0$ is then:
\begin{align}
    E^{(K,{\hat \theta_{K,N}})}(z^1,z^0_1,\dots,z^0_K) &= \frac{ \exp(g_{\hat \theta_{K,N}}(z^1))}{\frac{1}{K+1}\left (  \exp(g_{\hat \theta_{K,N}}(z^1)) + \sum_{k=1}^K \exp(g_{\hat \theta_{K,N}}(z^0_k)) \right )  }.
\end{align}

\label{thm:approx-gro}
Let the setting be like in \Cref{not:empirical-e-val}. 
Assume $P_1 \ll P_0$ and let $g_\theta :\Omega \to \mathbb{R}$ be a family of $\mathcal{B}$-measurable functions, $\theta \in \Theta$, with the following properties:
\begin{enumerate}[series=approx-gro-list]
    \item Compactness: $\Theta$ is a compact metric space. \label{it:compact}
    \item Continuity: for every $z \in \Omega$ the map $\theta \mapsto g_\theta(z)$ is continuous. \label{it:cont}
    \item Non-degeneracy: there exists a $\theta \in \Theta$ with $J_K(\theta) > -\infty$. \label{it:non-deg}
    \item Uniform integrable envelopes: \label{it:unif-int-envs}
    \begin{align}
        \mathbb{E}_{P_0}\left [  \sup_{\theta \in \Theta} g_\theta(Z^0)_+ \right ]  & < \infty, &
        \mathbb{E}_{P_1}\left [  \sup_{\theta \in \Theta} g_\theta(Z^1)_- \right ]  & < \infty.
    \end{align}
\end{enumerate}
Then, for fixed $K \ge 1$, we have the following \emph{uniform strong law of large numbers}  for the objective, that is the $\mathbb{P}_1$-almost-sure convergence:
\begin{align}
 \sup_{\theta \in \Theta} \left|  J_{K,N}(\theta) - J_K(\theta) \right|  &\overset{N \to \infty}{\longrightarrow} 0 \qquad \mathbb{P}_1\text{-a.s.}
\end{align}
Furthermore, for every near-maximizing sequence $(\hat \theta_{K,N})_{N \in \mathbb{N}_1}$ of $(J_{K,N})_{N \in \mathbb{N}_1}$ with optimization gaps $(\xi_{K,N})_{N \in \mathbb{N}_1}$ we have the $\mathbb{P}_1$-almost-sure convergences\footnote{Note that the expectation value $\mathbb{E}_{\mathbb{P}_1}$ integrates over the variables $(z^1,z^0_1,\dots,z^0_K)$ of $E^{(K,\hat \theta_{K,N})}$, but leaves the randomness from the fitting procedure in $\hat \theta_{K,N}$ intact. The ``$\mathbb{P}_1$-a.s.'' statement is then about the randomness in $\hat \theta_{K,N}$.}:
\begin{align}
\liminf_{N \to \infty}\mathbb{E}_{\mathbb{P}_1}[\log E^{(K,\hat \theta_{K,N})}] 
 &\ge \sup_{\theta \in \Theta} J_K(\theta) -\xi_K \qquad \mathbb{P}_1\text{-a.s.}
\end{align}
Now consider the maximizers $g^*_c: \Omega \to \mathbb{R} \cup \left \{  - \infty \right \} $ of $J_K$ from \Cref{prp:optimal-e-power-k} (in log space) for $c \in \mathbb{R}$:
\begin{align}
    g^*_c(z) &:= g^*(z) + c, & g^*(z) &:= \log \frac{dP_1}{dP_0}(z).
\end{align}
We now assume, in addition to the above, that we have the following properties:
\begin{enumerate}[resume=approx-gro-list]
    \item Approximating class: there exist $\theta \in \Theta$ and $\epsilon, c \in \mathbb{R}$ with $0 \le \epsilon < \infty$ such that: \label{it:approx-class}
    \begin{align}
        \sup_{z \in \Omega} \left|  g_\theta(z) - g^*_c(z) \right|  \le \epsilon.
    \end{align}
    \item Finite $\chi^2$-divergence: we have: $P_1 \ll P_0$ with $\chi^2(P_1\|P_0) < \infty$. \label{it:chi-sq-ft}
\end{enumerate}
Then we have \emph{approximate growth optimality} (AGRO) expressed as the following $\mathbb{P}_1$-almost-sure inequalities:
\begin{align}
     \underbrace{\operatorname{KL}(P_1\|P_0)}_{\text{maximal \textsc{e}-power}}  & \ge \underbrace{\liminf_{N \to \infty}   \mathbb{E}_{\mathbb{P}_1}[\log E^{(K,\hat \theta_{K,N})}]}_{\text{asymptotic learned \textsc{e}-power}} \\
     &\ge \underbrace{\operatorname{KL}(P_1\|P_0)}_{\text{maximal \textsc{e}-power}} \underbrace{-\log\left (  1 + \frac{\chi^2(P_1\|P_0)}{K+1} \right ) }_{\text{penalty for finite }K} \underbrace{-\frac{1}{2}\epsilon^2}_{\text{approximation gap}} \underbrace{- \xi_K}_{\text{optimization gap}}.
\end{align}
In particular, if $\operatorname{KL}(P_1\|P_0) > \frac{1}{2}\epsilon^2 + \sup_{K\in \mathbb{N}_1}\xi_K$, then we can find $K,N  \ge 1$ such that we achieve positive \textsc{e}-power $E_{\mathbb{P}_1}[\log E^{(K,\hat \theta_{K,N})}] >0$ for $H_1$ with high probability.

For deep neural networks $g_\theta$ the map:
    \begin{align}
        (\theta,z) & \mapsto g_\theta(z),
    \end{align}
    is continuous and one usually even has a Lipschitz type inequality, based on the used architecture:
    \begin{align}
        |g_\theta(z)| & \le C(\theta) \cdot (1+\|z\|),
    \end{align}
    with a constant $C(\theta)$ that is continuous in $\theta$.
    Furthermore, the class of deep neural networks is a universal approximator. So, on compact $\Omega$, we can adjust the architecture and the parameterization such that: 
    \begin{align}
        g_\theta & \approx g^*_c,
    \end{align}
    for some $\theta$ from some sufficiently big, but compact $\Theta$.
    So, the remaining envelope properties from \Cref{thm:approx-gro} reduce for deep neural networks to simple moment conditions:
    \begin{align}
        \mathbb{E}_{P_1}[\|Z^1\|] &< \infty, & \mathbb{E}_{P_0}[\|Z^0\|] &< \infty.
    \end{align}
So, for deep neural networks, in practice, we can argue that \Cref{thm:approx-gro} should hold on compact $\Omega$. For non-compact, but $\sigma$-compact, $\Omega$ one can exhaust the space $\Omega$ with compacta and apply \Cref{thm:approx-gro} individually on each compact subspace. We do not provide further technical details for this generalization here.

In practice, we can remove the ambiguity of the constant $c \in \mathbb{R}$ in the optimal function in \Cref{prp:optimal-e-power-k} and \Cref{thm:approx-gro} by introducing the following regularizer:
\begin{align}
    R_{K,N}(\theta) &:= \left|  \log \frac{1}{NK} \sum_{n=1}^N \sum_{k =1 }^K \exp(g_\theta(z^0_{n,k})) \right| ^2,
\end{align}
which enforces to keep $c \approx 1$ (or, $c \approx 0$ in log-space, resp.). 
We then minimize the following joint objective with a small regularization parameter $\kappa >0$:
\begin{align}
\hat \theta_{K,N}:\in  \operatorname*{argmax}_{\theta \in \Theta} \left (  J_{K,N}(\theta) - \kappa \cdot R_{K,N}(\theta) \right ) .
\end{align}
Alternatively, we can sample separate i.i.d.\ samples $(z^0_m)_{m \in [M]} \sim P_0$ with $M \gg 1$ \emph{after} training (with or without such regularization) and compute:
\begin{align}
    \hat c &:= \log \frac{1}{M}\sum_{m=1}^M \exp\left (  g_{\hat \theta_{K,N}}(z^0_m) \right ) ,  & \tilde g_{\hat \theta_{K,N}}(x) &:= g_{\hat \theta_{K,N}}(x) - \hat c.
\end{align}
With the above methods, we can remove the additive constant $c$ and achieve that: $g_{\hat \theta_{K,N}} \approx \log \frac{dP_1}{dP_0}$. 
Note that the constant, anyways, does not affect the \textsc{e}-variable $E^{(K,\theta)}$ of our form \Cref{eq:e-var-ratio}, and only helps to interpret $g_{\hat \theta_{K,N}}$ as a log-likelihood ratio.

\label{rem:clipping-emp}
 In order to prevent a learned \textsc{e}-variable $E^{(K,{\hat \theta_{K,N}})}$, which might by chance become close to zero (log-unbounded from below), to quickly destroy the wealth process $W_t$, we could introduce a regularizing clipping parameter $\lambda \in [0,1]$, as described in \Cref{rem:clipping}:
\begin{align}
    E^{(K,\theta,\lambda)}(z^1,z^0_1,\dots,z^0_K) 
    &:= (1-\lambda) + \lambda \cdot E^{(K,\theta)}(z^1,z^0_1,\dots,z^0_K)\\
    & = (1-\lambda) + \lambda \cdot
    \frac{ \exp(g_\theta(z^1))}{\frac{1}{K+1}\left (  \exp(g_\theta(z^1)) + \sum_{k=1}^K \exp(g_\theta(z^0_k)) \right )  }.
\end{align}
This would, as mentioned in \Cref{rem:clipping}, restore the explicit type-II error bounds from \Cref{thm:type-II-error}. 
However, there are different ways to choose $\lambda$, as we will indicate in the following.

a.) A typical, simple and effective choice for $\lambda$ would be to just set $\lambda_1 := \frac{1}{2}$.

b.) Based on the observation, that we already have the deterministic upper bound:
 \begin{align}
     \log E^{(K,\theta)} & \le \log (K+1),
 \end{align}
 a symmetric lower bound could be achieved by the choice $\lambda_K := \frac{K}{K+1}$. Then we would just get:
\begin{align}
    E^{(K,\theta,\lambda_K)} 
    &= \frac{1}{K+1} + \frac{K}{K+1}\cdot E^{(K,\theta)} 
    = \frac{1}{K+1} +\frac{ \exp(g_\theta(z^1))}{\frac{1}{K}\left (  \exp(g_\theta(z^1)) + \sum_{k=1}^K \exp(g_\theta(z^0_k)) \right )  },
\end{align}
 with the symmetric lower and upper bounds:
 \begin{align}
    - \log (K+1) \le  \log E^{(K,\theta,\lambda_K)} & \le \log(K+1).
 \end{align}

 c.) Alternatively, we could jointly fit $\theta$ and $\lambda$, to maximize \textsc{e}-power, similarly to before:
\begin{align}
   (\hat \theta_{K,N},\hat \lambda_{K,N}) :\in  \operatorname*{argmax}_{\substack{\theta \in \Theta\\ \lambda \in [0,1]}}
    J_{K,N}(\theta,\lambda), &  &J_{K,N}(\theta,\lambda)&:= \frac{1}{N}\sum_{n=1}^N \log E^{(K,\theta,\lambda)}\left (  z^1_n,(z^0_{n,k})_{k \in [K]} \right ) .
\end{align}
Since $\lambda$ might, in this fitting procedure, still become too overconfident ($\hat \lambda_{K,N} \approx 1$), we could afterwards scale it down by a fixed hyperparameter $\rho \in [0,1)$, e.g.\ again $\rho_1=\frac{1}{2}$, $\rho_2=\frac{2}{3}$, $\rho_3=\frac{3}{4}$, $\rho_4=\frac{4}{5}$ or $\rho_K = \frac{K}{K+1}$, and put:
\begin{align}
    \tilde \lambda_{K,N} &:= \rho \cdot \hat \lambda_{K,N},
\end{align}
and use the \textsc{e}-variable
\begin{align}
   E^{(K,\rho,N)} := E^{(K,\hat \theta_{K,N},\tilde \lambda_{K,N})},
\end{align}
which then always produces the deterministic bounds:
\begin{align}
    \log (1 - \rho) \le \log E^{(K,\rho,N)} \le \log (K+1).
\end{align}

d.) There are further options, like providing a whole schedule $(\lambda_t)_{t \in \mathbb{N}_0}$ over time, or even learning such a schedule (but only on past data). All these choices would not violate the conditional \textsc{e}-variable conditions and all guarantees from \Cref{thm:type-I-error} and \Cref{thm:type-II-error} would still hold with the corresponding numbers.

There are two considerations for the choice of the number $K \ge 1$ that restrict the power of $E^{(K,\theta)}$.

a.) The first obstruction is the deterministic upper bound: \begin{align}
      E^{(K,\theta)} & \le K+1,
\end{align}
which restricts the \textsc{e}-power to:
\begin{align}
  \mathbb{E}_{\mathbb{P}_1}\left [  \log E^{(K,\theta)}\right ]  & \le \log(K+1).
\end{align}
If we even want to have a chance to be approximately close to the upper limit of $\operatorname{KL}(P_1\|P_0)$ then at least the upper bound should be close to or even exceed it:
\begin{align}
    \log(K+1) & \gtrsim \operatorname{KL}(P_1\|P_0),
\end{align}
leading to the following condition for the choice of $K$:
\begin{align}
    K+1 & \gtrsim \exp(\operatorname{KL}(P_1\|P_0)) 
    \approx \exp\left (  \frac{1}{M} \sum_{m=1}^M g_{\hat \theta_{K,N}}(z^1_m)\right ) , & (z^1_m)_{m \in [M]} \overset{\text{i.i.d.}}{\sim} P_1.
\end{align}
which one could track and adjust during training.

b.) The second obstruction is the lower bound from \Cref{thm:approx-gro} for the optimized limit \textsc{e}-variable:
\begin{align}
    \mathbb{E}_{\mathbb{P}_1}[\log E^{(K,\hat \theta)}] \ge \quad \operatorname{KL}(P_1\|P_0) - \log\left (  1 + \frac{\chi^2(P_1\|P_0)}{K+1} \right )  - \frac{1}{2}\epsilon^2.
\end{align}
If we wanted the term for the penalty for finite $K$ to become of size smaller than $\delta > 0$  we could require:
\begin{align}
  \delta & \overset{!}{\gtrsim}  \frac{\chi^2(P_1\|P_0)}{K+1} \ge \log\left (  1 + \frac{\chi^2(P_1\|P_0)}{K+1}\right ) .
\end{align}
This would lead to the following criterion:
\begin{align}
    K+1  \gtrsim \frac{\chi^2(P_1\|P_0)}{\delta} 
    &\approx \frac{1}{\delta} \cdot \frac{1}{M}
    \sum_{m=1}^M \left (  \exp(g_{\hat \theta_{K,N}}(z^0_m))-1\right ) ^2, & (z^0_m)_{m \in [M]} \overset{\text{i.i.d.}}{\sim} P_0 \\
    &\approx \frac{1}{\delta} \cdot \left (  \frac{1}{M}
    \sum_{m=1}^M \exp(g_{\hat \theta_{K,N}}(z^1_m)) - 1\right ) , & (z^1_m)_{m \in [M]} \overset{\text{i.i.d.}}{\sim} P_1.
\end{align}
As before, also this quantity could be checked and adjusted during training.

Another popular and rather stable training objective in machine learning for learning density ratios comes from another variational form of the $\operatorname{KL}$-divergence, see \cite{Ngu10, Bel18, Poo019}: 
\begin{align}
 \operatorname{KL}(P_1\|P_0) &= \sup_{g} \left \{  \mathbb{E}_{P_1}[g] - \mathbb{E}_{P_0}[\exp(g)] + 1 \right \} , \qquad \text{with unique maximizer:} \qquad g^*(z) = \log \frac{dP_1}{dP_0}(z).
\end{align}
Here, we then would, again, maximize the corresponding empirical version with samples $(z^1_n)_{n \in [N_1]} \overset{\text{i.i.d.}}{\sim} P_1$ and $(z^0_n)_{n \in [N_0]} \overset{\text{i.i.d.}}{\sim} P_0$:
\begin{align}
   \hat \theta_{N_1,N_0} &:\in \operatorname*{argmax}_{\theta \in \Theta} I_{N_1,N_0}(\theta), 
   & I_{N_1,N_0}(\theta) &:= \frac{1}{N_1}\sum_{n=1}^{N_1} g_\theta(z^1_n) - \frac{1}{N_0}\sum_{n=1}^{N_0} \exp(g_\theta(z^0_n)) + 1.
\end{align}
The estimator is known to have less bias, but higher variance. 
After training, one can use $g_{\hat \theta_{N_1,N_0}}$ in our \textsc{e}-variable from \Cref{eq:e-var-ratio} with some chosen $K \ge 1$.

Recall that in \Cref{sec:e-val-constr} we used the construction from \Cref{eq:E-val-K-h} to approximate the \textsc{e}-variable from \Cref{eq:E-val-h-norm}:
\begin{align}
  \tilde h(z^1):= \frac{h(z^1)}{\mathbb{E}_{P_0}[h]} &\approx   \frac{h(z^1)}{\frac{1}{K+1}\left (  h(z^1)+\sum_{k=1}^K h(z^0_k)\right ) }  =: E^{(K,h)}(z^1,z^0_1,\dots, z^0_K),
\end{align}
where we then optimized $h$ in \Cref{thm:approx-gro} to receive: $h=\exp(g_{\hat \theta_{K,N}})$ with $g_{\hat \theta_{K,N}} \approx \log \frac{dP_1}{dP_0}$, which is approximately growth optimal in the long run and minimizes average rejection time, see \Cref{rem:rejection-time}.  
In contrast, following \cite{For26a}, we now want to consider the case where the time horizon $T \in \mathbb{N}$ for the real experiments $(x_t)_{t \in [T]} \overset{\text{i.i.d.}}{\sim} Q$ is a priori known and finite. For this we want to fix $h$ from above, but we now modify it with an \emph{inverse temperature} regularization parameter $\beta \in \mathbb{R}_{>0}$:
\begin{align}
    h_\beta(z^1) := \frac{h(z^1)^\beta}{\mathbb{E}_{P_0}[h^\beta]} &\approx   \frac{h(z^1)^\beta}{\frac{1}{K+1}\left (  h(z^1)^\beta+\sum_{k=1}^K h(z^0_k)^\beta\right ) }  =: E^{(K,h,\beta)}(z^1,z^0_1,\dots, z^0_K),
\end{align}
in order to minimize the type-II error at the one future time $T$, when at present time $t \le T$, when we have already observed $W_{t-1}$:
\begin{align}
    \beta_{t-1} : \in \operatorname*{argmin}_{\beta > 0} P_1\left (  W_T \le \frac{1}{\alpha} \,\middle|\, \mathcal{F}_{t-1}\right ) . 
\end{align}
Assume for now, that we are in the idealized case, where we have directly used $h_\beta$ as \textsc{e}-variables; then the above reduces to:
\begin{align}
P_1\left (  W_T \le \frac{1}{\alpha} \,\middle|\, \mathcal{F}_{t-1}\right )  
&= P_1\left (  \sum_{n=t}^T \log h_\beta(z_t^1) \le \log\frac{1}{\alpha} - \log W_{t-1} \,\middle|\, \mathcal{F}_{t-1}\right )  \\
&= P_1\Bigg( \frac{1}{T-t+1}\sum_{n=t}^T \log h(z_t^1) \le \frac{1}{\beta}\bigg( \frac{\log\frac{1}{\alpha} - \log W_{t-1}}{T-t+1} + \log \mathbb{E}_{P_0}[h^\beta] \bigg)  \,\Bigg|\, \mathcal{F}_{t-1} \Bigg).
\end{align}
Note that only the rhs depends on $\beta$, so minimizing that type-II error reduces to minimizing the rhs w.r.t.
 $\beta$, which we only need for the case when we have not rejected $H_1$ yet, that is, if $W_{t-1} \le \frac{1}{\alpha}$. We  thus arrive at the exact objective:
\begin{align}
    \beta_{t-1} \in \operatorname*{argmin}_{\beta > 0} \frac{1}{\beta} \Bigg(\underbrace{\frac{(\log \frac{1}{\alpha} - \log W_{t-1})_+ }{T-t+1}}_{=:\ell_{t-1}} + \underbrace{\log \mathbb{E}_{P_0}\left [  h^\beta\right ] }_{=:\psi(\beta)} \Bigg),
\end{align}
where we interpret $\ell_{t-1}$ as the residual target evidence for rejecting $H_1$ per remaining time step until time $T$. 
The optimization problem can then numerically be solved with Newton iteration:
\begin{align}
    \beta^{(i+1)} := \beta^{(i)} - \frac{\beta^{(i)} \cdot \psi'(\beta^{(i)}) - \psi(\beta^{(i)}) - \ell_{t-1}}{\beta^{(i)} \cdot \psi''(\beta^{(i)})}, \qquad \text{ with: }
\end{align}
\begin{align}
        \psi(\beta) &= \log \mathbb{E}_{P_0}[h^\beta], & 
        \psi'(\beta) &= \frac{\mathbb{E}_{P_0}[h^\beta\log h]}{\mathbb{E}_{P_0}[h^\beta]}  & 
        \psi''(\beta) &= \frac{\mathbb{E}_{P_0}[h^\beta(\log h)^2]}{\mathbb{E}_{P_0}[h^\beta]} - \psi'(\beta)^2,
\end{align}
where each expectation value is replaced by the empirical counterparts based on the same one batch of i.i.d.\ samples $(z^0_m)_{m \in [M]} \overset{\text{i.i.d.}}{\sim} P_0$ and with $h=\exp(g_{\hat \theta_{K,N}})$.
After convergence, $i \to \infty$, practically after $3-5$ rounds of iterations, one has found an approximate $\beta_{t-1}:=\beta^{(\infty)}$, which one can use, at time $t \in [T]$, for the conditional \textsc{e}-variable: 
\begin{align}
  E_t(z^1,z^0_1,\dots,z^0_K) 
&:= \frac{ \exp(\beta_{t-1}\cdot g_{\hat \theta_{K,N}}(z^1))}{\frac{1}{K+1}\left (  \exp(\beta_{t-1}\cdot g_{\hat \theta_{K,N}}(z^1)) + \sum_{k=1}^K \exp(\beta_{t-1}\cdot g_{\hat \theta_{K,N}}(z^0_k)) \right )  }.
\end{align}  
At the next time step $t+1$, this can be repeated, leading to an adaptive predictive sequence $(\beta_t)_{t \in [T]}$ of inverse temperatures. 
This, of course, can be combined with the clipping regularization from \Cref{rem:clipping-emp}. Note that, even with these $\beta$ values in place, each of which is only dependent on their own past, the anytime type-I error guarantees from \Cref{thm:type-I-error} still hold.

\label{thm:ville}
    Let $(W_t)_{t \in \mathbb{N}_0}$ be a non-negative supermartingale, $W_t:\, (\Omega,\mathcal{B},P_0) \to [0,\infty]$, $t \in \mathbb{N}_0$, adapted to the filtration $\mathcal{F}=(\mathcal{F}_t)_{t \in \mathbb{N}_0}$, $\mathcal{F}_t \subseteq \mathcal{B}$ and w.r.t.\ probability measure $P_0$. 
    Then for every $\alpha \in (0,1]$ we have the inequality:
    \begin{align}
        P_0\left (  \exists t \in \mathbb{N}_0.\; W_t > \frac{1}{\alpha} \right )  \le \alpha \cdot \mathbb{E}_{P_0}[W_0].
    \end{align}

\label{thm:azuma}
Let $(L_t)_{t \in \mathbb{N}_0}$ be sequence of random variables $L_t:\, (\Omega,\mathcal{B},P_1) \to \mathbb{R}$, $t \in \mathbb{N}_0$, $L_0:=0$, adapted to the filtration $\mathcal{F}=(\mathcal{F}_t)_{t \in \mathbb{N}_0}$,  $\mathcal{F}_t \subseteq \mathcal{B}$ and w.r.t.\ probability measure $P_1$. Further assume that for every $t \in \mathbb{N}_1$ there are constants $a_t, b_t, c_t \in \mathbb{R}$ such that:
\begin{align}
    a_t &\le L_t \le b_t \quad P_1\text{-a.s.}, & 
    c_t & \le \mathbb{E}_{P_1}[L_t|\mathcal{F}_{t-1}]
    \quad P_1\text{-a.s.}.
\end{align}
Then for every $\ell \in \mathbb{R}$ and $t \in \mathbb{N}_1$ we have:
\begin{align}
    P_1\left (  \sum_{n=1}^t L_n \le \ell \right )  & 
    \le \exp\left (  - \frac{2\left (  \sum_{n=1}^t c_n - \ell\right ) _+^2}{\sum_{n=1}^t (b_n-a_n)^2} \right ) .
\end{align}
If, in particular, $b_t-a_t \le d >0$ and $c_t \ge c$ for all $t \in \mathbb{N}_1$ then we get:
\begin{align}
    P_1\left (  \sum_{n=1}^t L_n \le \ell \right )  & 
    \le \exp\left (  - 2t \cdot \frac{\left (  c - \frac{1}{t}\ell \right ) _+^2}{d^2} \right ) .
\end{align}

\label{prf:prp:optimal-e-power-k}
 In the following we abbreviate $\mathcal{X}:=\Omega^{K+1}$ and 
$x=(z^1,z^0_1,\dots,z^0_K) \in \mathcal{X}$.
We abbreviate: $\mathcal{Y} := \left \{  0,1,\dots,K\right \} $ and the uniform distribution on $\mathcal{Y}$:
\begin{align}
    P(Y = k) &:= \frac{1}{K+1}.
\end{align}
For $k \in \mathcal{Y}$ we then abbreviate the probability distribution on $\mathcal{X}$ with random variable $X=(X_0,\dots,X_K)$:
\begin{align}
    \mathbb{P}(X|Y=k) &:= P_0(X_0) \otimes \cdots \otimes P_0(X_{k-1}) \otimes P_1(X_k) \otimes P_0(X_{k+1}) \otimes \cdot \otimes P_0(X_K).
\end{align}
We further put:
\begin{align}
    Q^{(K,h)}(Y=k|X=x) &:= \frac{h(x_k)}{ \sum_{j=0}^K h(x_j)}.
\end{align}
Then we have:
\begin{align}
    \mathbb{E}_{P(X|Y) \otimes P(Y)}\left [  \log Q^{(K,h)}(Y|X) \right ] 
    &= \frac{1}{K+1} \sum_{k=0}^K \mathbb{E}_{P(X|Y=k)} \left [  \log \left (  \frac{h(X_k)}{ \sum_{j=0}^K h(X_j)} \right )  \right ]  \\
    &= \mathbb{E}_{P(X|Y=0)} \left [  \log \left (  \frac{h(X_0)}{ \sum_{j=0}^K h(X_j)} \right )  \right ]  \\
    &= \mathbb{E}_{\mathbb{P}_1}\left [  \log E^{(K,h)}\right ]  - \log(K+1).
\end{align}
With this we get:
\begin{align}
    \operatorname*{argmax}_{h} \mathbb{E}_{\mathbb{P}_1}\left [  \log E^{(K,h)}\right ]  
    &= \operatorname*{argmax}_{h} \mathbb{E}_{P(X|Y) \otimes P(Y)}\left [  \log Q^{(K,h)}(Y|X) \right ]  \\
    &= \operatorname*{argmin}_{h} \mathbb{E}_{P(X)} \left [  \operatorname{KL}(P(Y|X)\|Q^{(K,h)}(Y|X)) \right ] .
\end{align}
Since $\operatorname{KL}$ is a proper divergence, the rhs is minimized if and only if it equals zero if and only if:
\begin{align}
    P(Y|X) &= Q^{(K,h)}(Y|X) \qquad P(X)\text{-a.s.}
\end{align}
Since we assumed $P_1 \ll P_0$, we also have $P(X|Y=k) \ll P_0^{\otimes(K+1)}$ and $P(X) \ll P_0^{\otimes(K+1)}$. So we can express the lhs via Bayes's theorem in terms of densities $p(x|k)$ and $p(x)$:
\begin{align}
    P(Y=k|X=x) &= \frac{p(x|k)}{p(x)} P(Y=k)
    = \frac{\frac{dP_1}{dP_0}(x_k)}{\frac{1}{K+1}\sum_{j=0}^K \frac{dP_1}{dP_0}(x_j)} \frac{1}{K+1} = \frac{\frac{dP_1}{dP_0}(x_k)}{\sum_{j=0}^K \frac{dP_1}{dP_0}(x_j)}.
\end{align}
So, the condition for minimization holds if and only if for $P(X)$-almost-all $x \in \mathcal{X}$ and all $k \in \mathcal{Y}$ we have:
\begin{align}
\frac{\frac{dP_1}{dP_0}(x_k)}{\sum_{j=0}^K \frac{dP_1}{dP_0}(x_j)} 
= \frac{h(x_k)}{ \sum_{j=0}^K h(x_j)}. \label{eq:ratio-normed}
\end{align}
Taking ratios for $k,l \in \mathcal{Y}$ gives $P(X)$-almost-all $x \in \mathcal{X}$:
\begin{align}
h(x_k) \cdot \frac{dP_1}{dP_0}(x_l) &= h(x_l) \cdot \frac{dP_1}{dP_0}(x_k).
\end{align}
Inegrating over $P_0(dx_l)$ gives for every $k \in \mathcal{Y}$:
\begin{align}
    h(x_k) &=  h(x_k) \cdot \underbrace{\mathbb{E}_{P_0}\left [  \frac{dP_1}{dP_0}\right ] }_{=1} = 
    \underbrace{\mathbb{E}_{P_0}\left [  h \right ] }_{=:c >0} \cdot \frac{dP_1}{dP_0}(x_k) =  c \cdot \frac{dP_1}{dP_0}(x_k), 
\end{align}
which implies that for some $c >0 $, $P_0$-almost-all $z \in \Omega$:
\begin{align}
    h(z) &=    c \cdot \frac{dP_1}{dP_0}(z). \label{eq:ratio-const}
\end{align}
Note that \Cref{eq:ratio-const} also directly implies \Cref{eq:ratio-normed}. 
This then shows that such an $h$ maximizes the \textsc{e}-power $\mathbb{E}_{\mathbb{P}_1}\left [  \log E^{(K,h)}\right ] $.
This shows the equivalence.

\label{prf:thm:approx-gro}
1.) In the following we abbreviate $\mathcal{X}:=\Omega^{K+1}$ and 
$x=(z^1,z^0_1,\dots,z^0_K) \in \mathcal{X}$.
First note that we have for every $x \in \mathcal{X}$ the uniform bound:
\begin{align}
     E^{(K,\theta)}(x) &=  \frac{ \exp(g_\theta(z^1))}{\frac{1}{K+1}\left (  \exp(g_\theta(z^1)) + \sum_{k=1}^K \exp(g_\theta(z^0_k)) \right )  } \le K+1.
\end{align}
We further abbreviate:
\begin{align}
    \ell_\theta(x) &:= \log E^{(K,\theta)}(x) = g_\theta(z^1) - \log \left (  \exp(g_\theta(z^1)) + \sum_{k=1}^K \exp(g_\theta(z^0_k)) \right )  + \log (K+1).
\end{align}
Note that we have the bounds:
\begin{align}
    \log(K+1) \ge \ell_\theta(x) & \ge g_\theta(z^1) - \max\left (  g_\theta(z^1), g_\theta(z^0_1), \dots, g_\theta(z^0_K) \right )  \\
    &\ge - g_{\theta,-}(z^1) - \max_{k \in [K]} g_{\theta,+}(z^0_k),
\end{align}
which implies the two bounds:
\begin{align}
    \ell_{\theta,+}(x) & \le \log(K+1) < \infty, &
    \ell_{\theta,-}(x) & \le g_{\theta,-}(z^1) + \max_{k \in [K]} g_{\theta,+}(z^0_k).
\end{align}
For the latter we take $\sup_{\theta \in \Theta}$ and then $\mathbb{E}_{\mathbb{P}_1}$ and get:
\begin{align}
   \mathbb{E}_{\mathbb{P}_1}\left [ \sup_{\theta \in \Theta}\ell_{\theta,-}(X)\right ]  
   & \le \mathbb{E}_{P_1}\left [  \sup_{\theta \in \Theta} g_{\theta,-}(Z^1)\right ]  + \mathbb{E}_{P_0}\left [ \max_{k \in [K]} \sup_{\theta \in \Theta} g_{\theta,+}(Z^0_k)\right ]  \\
   & \le \mathbb{E}_{P_1}\left [  \sup_{\theta \in \Theta} g_{\theta,-}(Z^1)\right ]  + \sum_{k \in [K]} \mathbb{E}_{P_0}\left [  \sup_{\theta \in \Theta} g_{\theta,+}(Z^0_k)\right ]  \\
   & \overset{\ref{it:unif-int-envs}}{<} \infty,
\end{align}
where the latter holds by assumption \ref{it:unif-int-envs} about the integrable envelopes. Together we get the finite integrable envelope bound:
\begin{align}
    \mathbb{E}_{\mathbb{P}_1}\left [  \sup_{\theta \in \Theta}|\ell_{\theta}(X)| \right ]  & < \infty. \label{eq:log-e-env-integrable}
\end{align}

2.) Also note that by assumption \ref{it:cont}, $\ell_\theta(x)$ is continuous in $\theta$ for every fixed $x \in \mathcal{X}$. By the integrability condition from \Cref{eq:log-e-env-integrable} we can use the dominated convergence theorem to show that also:
\begin{align}
    J_K(\theta) &= \mathbb{E}_{\mathbb{P}_1}[\ell_\theta(X)]
\end{align}
is continuous in $\theta \in \Theta$. Since $\Omega$ is compact by assumption \ref{it:compact} we even get that $J_K$ is uniformly continuous.

3.) We now want to prove the \emph{uniform law of large numbers}:
\begin{align}
    \sup_{\theta \in \Theta} \left|  J_{K,N}(\theta) - J_K(\theta) \right|  \overset{N \to \infty}{\longrightarrow} 0 \qquad \mathbb{P}_1\text{-a.s.}
\end{align}
To show this, let $\epsilon > 0$ be fixed.

a.) Now recall:
\begin{align}
    J_{K,N}(\theta) & = \frac{1}{N}\sum_{n=1}^N \ell_\theta(X_n), & J_K(\theta) &= \mathbb{E}_{\mathbb{P}_1}\left [  J_{K,N}(\theta)\right ] .
\end{align}
Since $J_K$ is uniformly continuous, there exists $\eta_1 > 0$ such that for all $\theta',\theta" \in \Theta$ we have:
\begin{align}
    d(\theta',\theta") \le \eta_1 & \implies |J_K(\theta') - J_K(\theta") | < \epsilon/4.
\end{align}

b.) As a next step, for $\eta > 0$ and $x \in \mathcal{X}$ define:
\begin{align}
    D_\eta(x) &:= \sup_{\substack{\theta',\theta" \in \Theta\\d(\theta',\theta")\le \eta}} |\ell_{\theta'}(x) - \ell_{\theta"}(x) |.
\end{align}
Note that $D_\eta(x)$ in monotone non-decreasing in $\eta$ for each fixed $x \in \mathcal{X}$ with:
\begin{align}
    \lim_{\eta \to 0}  D_\eta(x)  & = 0,
\end{align}
due to the uniform continuity of $\ell_{\theta}(x)$ in $\theta$, combining the assumptions of continuity \ref{it:cont} and compactness  \ref{it:compact}. 
Further note that we have the bound:
\begin{align}
  0 \le  D_\eta(x)  & \le 2 \cdot \sup_{\theta \in \Theta}|\ell_{\theta}(x)|,
\end{align}
where the upper bound is integrable by \Cref{eq:log-e-env-integrable}.
The dominated convergence theorem thus implies:
\begin{align}
    \lim_{\eta \to 0} \mathbb{E}_{\mathbb{P}_1}\left [  D_\eta(X) \right ]  & = 0.
\end{align}
So, we can choose $\eta >0$ small enough and with $ \eta_1 > \eta > 0$ such that:
\begin{align}
    \mathbb{E}_{\mathbb{P}_1}\left [  D_\eta(X) \right ]  & < \epsilon/4.
\end{align}
By the strong law of large numbers we have the $\mathbb{P}_1$-almost-sure convergence:
\begin{align}
    \frac{1}{N}\sum_{n=1}^N D_\eta(X_n) &\overset{N\to\infty}{\longrightarrow} \mathbb{E}_{\mathbb{P}_1}\left [  D_\eta(X) \right ]   < \epsilon/4.
\end{align}
So, for $\mathbb{P}_1$-almost-all realizations $\omega \in \Omega$ there exists an $N_0(\omega) \in \mathbb{N}$ such that for all $N \ge N_0(\omega)$ we have:
\begin{align}
    \frac{1}{N}\sum_{n=1}^N D_\eta(X_n(\omega)) &  < \epsilon/2.
\end{align}

c.) By assumption \ref{it:compact} the space $\Omega$ is a compact metric space with some metric $d$. So, there are finitely many $\theta_1,\dots, \theta_M \in \Omega$ with:
\begin{align}
    \Omega &\subseteq \bigcup_{m \in [M]} B(\theta_m,\eta),
\end{align}
where $\eta>0$ was fixed in the previous points and $B(\theta_m,\eta)$ is the (closed) ball of radius $\eta$ around $\theta_m$. So, for every $\theta \in \Omega$ we can pick an index $j(\theta) \in [M]$ such that:
\begin{align}
    d(\theta,\theta_{j(\theta)}) \le \eta,
\end{align}
 which then implies:
\begin{align}
    |J_K(\theta) - J_K(\theta_{j(\theta)}) | < \epsilon/4.
\end{align}

d.) Now consider $\theta \in \Omega$ and $m=j(\theta) \in [M]$. Then we have:
\begin{align}
    \left|  J_{K,N}(\theta) - J_{K,N}(\theta_m) \right| 
    & = \left|  \frac{1}{N} \sum_{n=1}^N \left (  \ell_\theta(X_n) - \ell_{\theta_m}(X_n) \right )  \right|  \\
    & \le  \frac{1}{N} \sum_{n=1}^N \left|  \ell_\theta(X_n) - \ell_{\theta_m}(X_n) \right|  \\
    & \le \frac{1}{N} \sum_{n=1}^N D_\eta(X_n)  \\
    & < \epsilon/2,
\end{align}
for $\mathbb{P}_1$-almost-all realizations $\omega \in \Omega$ and all $N \ge N_0(\omega)$.

e.) The strong law of large numbers shows that for every $m \in [M]$ we have the $\mathbb{P}_1$-almost-sure convergence:
\begin{align}
    J_{K,N}(\theta_m) & \overset{N\to\infty}{\longrightarrow} J_K(\theta_m),
\end{align}
and since $M$ is finite also the $\mathbb{P}_1$-almost-sure convergence:
\begin{align}
   \max_{m \in [M]} \left|  J_{K,N}(\theta_m) - J_K(\theta_m) \right|  & \overset{N\to\infty}{\longrightarrow} 0,
\end{align}
So, for $\mathbb{P}_1$-almost-all realizations $\omega \in \Omega$ and all $N \ge N_0(\omega)$ we have:
\begin{align}
   \max_{m \in [M]} \left|  J_{K,N}(\theta_m) - J_K(\theta_m) \right|  & < \epsilon/4.
\end{align}

f.) Putting everything together shows that for fixed $\epsilon >0$ and $\mathbb{P}_1$-almost-all realizations $\omega \in \Omega$, all $\theta \in \Theta$ and all $N \ge N_0(\omega)$, and with $m=j(\theta) \in [M]$, we have:
\begin{align}
    \left|  J_{K,N}(\theta) - J_K(\theta) \right|  
    & \le \underbrace{\left|  J_{K,N}(\theta) - J_{K,N}(\theta_m) \right| }_{\le \frac{1}{N} \sum_{n=1}^N D_\eta(X_n) < \epsilon/2}
    + \underbrace{\left|  J_{K,N}(\theta_m) - J_K(\theta_m) \right| }_{< \epsilon/4}
    + \underbrace{\left|  J_K(\theta_m) - J_K(\theta) \right| }_{<\epsilon/4} 
     < \epsilon.
\end{align}
Note that, due to the uniform bound involving $D_\eta$, the bound $N_0(\omega)$ depends only on the realization $\omega \in \Omega$ (and $\epsilon$), but crucially not on $\theta$.
We thus get:
\begin{align}
    \sup_{\theta \in \Theta} \left|  J_{K,N}(\theta) - J_K(\theta) \right|  
    & \le  \epsilon.
\end{align}
This thus shows the \emph{uniform law of large numbers}:
\begin{align}
   \Delta_{K,N} := \sup_{\theta \in \Theta} \left|  J_{K,N}(\theta) - J_K(\theta) \right|  \overset{N \to \infty}{\longrightarrow} 0 \qquad \mathbb{P}_1\text{-a.s.}
\end{align}

4.) We now further have the (near-)maximizing sequence $(\hat \theta_{K,N})_{N \in \mathbb{N}}$, i.e.\ for all $N \in \mathbb{N}$:
\begin{align}
    J_{K,N}(\hat \theta_{K,N}) & \ge \sup_{\theta \in \Theta}  J_{K,N}(\theta) - \xi_{K,N} &  \limsup_{N\to \infty}\xi_{K,N} = \xi_K \in \mathbb{R}_{\ge 0} \qquad \mathbb{P}_1\text{-a.s.}
\end{align}
By definition of $\Delta_{K,N}$ we now have:
\begin{align}
 \sup_{\theta \in \Theta}  J_K(\theta) \ge  J_K(\hat \theta_{K,N}) & = J_{K,N}(\hat \theta_{K,N}) + J_K(\hat \theta_{K,N}) - J_{K,N}(\hat \theta_{K,N}) \\
    & \ge J_{K,N}(\hat \theta_{K,N}) - \left|  J_K(\hat \theta_{K,N}) - J_{K,N}(\hat \theta_{K,N}) \right|    \\
    &\ge J_{K,N}(\hat \theta_{K,N}) - \Delta_{K,N} \\
    &\ge \sup_{\theta \in \Theta}  J_{K,N}(\theta) - \Delta_{K,N} - \xi_{K,N} \\
    & \overset{(*)}{\ge} \sup_{\theta \in \Theta}  J_K(\theta) - 2\Delta_{K,N} - \xi_{K,N}.
\end{align}
To get $(*)$ observe that we have:
\begin{align}
    J_{K,N}(\theta) & = J_K(\theta) + J_{K,N}(\theta) - J_K(\theta)  \\
    & \ge J_K(\theta) - \left|  J_{K,N}(\theta) - J_K(\theta) \right|    \\
    &\ge J_K(\theta) - \Delta_{K,N},
\end{align}
which gives:
\begin{align}
    \sup_{\theta \in \Theta} J_{K,N}(\theta) & \ge \sup_{\theta \in \Theta} J_K(\theta) - \Delta_{K,N}.
\end{align}
Altogether, we have:
\begin{align}
 \sup_{\theta \in \Theta}  J_K(\theta) \ge  J_K(\hat \theta_{K,N}) & \ge \sup_{\theta \in \Theta}  J_K(\theta) - 2\Delta_{K,N} - \xi_{K,N} \qquad \mathbb{P}_1\text{-a.s.},
\end{align}
with:
\begin{align}
 \limsup_{N \to \infty}\Delta_{K,N} & =0, & \limsup_{N \to \infty} \xi_{K,N} &= \xi_K, \qquad \mathbb{P}_1\text{-a.s.}.
\end{align}
This then implies:
\begin{align}
   \liminf_{N \to \infty} J_K(\hat \theta_{K,N}) &\ge \sup_{\theta \in \Theta}  J_K(\theta) - \xi_K \qquad \mathbb{P}_1\text{-a.s.}
\end{align}
This shows another main claim of \Cref{thm:approx-gro}.

5.) g.) For the final main claim, we need to show the inequality:
\begin{align}
   J_K(g) & \ge J_K(g_c^*) - \frac{1}{2}\epsilon^2, \qquad \text{ whenever }\qquad \|g-g^*_c\|_\infty \le \epsilon.
\end{align}
For this we introduce the curve in function space, $s \in \mathbb{R}$:
\begin{align}
    g_s(z) &:= g^*_c(z) + s \cdot v(z), & v(z) &:=  g(z) - g^*_c(z) \in [-\epsilon,\epsilon].
\end{align}
and 
\begin{align}
     x&:=(z^1,z^0_1,\dots,z^0_K), &
    \pi_k(s,x) &:= \frac{\exp(g_s(x_k))}{\sum_{j=0}^K \exp(g_s(x_j))}, .
\end{align}
We then introduce:
\begin{align}
  J(s) := J_K(g_s) 
    & = \mathbb{E}_{\mathbb{P}_1}\left [  g_s(X_0) - \log\left (  \sum_{k=0}^K \exp(g_s(X_k)) \right )   \right ]  + \log(K+1).
\end{align}
With this we get the derivatives:
\begin{align}
    J'(s) &= \mathbb{E}_{\mathbb{P}_1}\left [  v(X_0) - \sum_{k=0}^K \pi_k(s,X) \cdot  v(X_k) \right ] , \\
    J''(s) &= -\mathbb{E}_{\mathbb{P}_1}\left [  \sum_{k=0}^K \pi_k(s,X) \cdot \left (  v(X_k) - \sum_{j=0}^K \pi_j(s,X) \cdot  v(X_j) \right )  \cdot  v(X_k) \right ]  \\
    &= -\mathbb{E}_{\mathbb{P}_1}\left [  \sum_{k=0}^K \pi_k(s,X) \cdot v(X_k)^2 - \left (  \sum_{k=0}^K \pi_k(s,X) \cdot  v(X_k)  \right ) ^2 \right ]  \\
    &= -\mathbb{E}_{\mathbb{P}_1}\left [  \sum_{k=0}^K \pi_k(s,X) \cdot v(X_k)^2 \right ]  + \mathbb{E}_{\mathbb{P}_1}\left [ \left (  \sum_{k=0}^K \pi_k(s,X) \cdot  v(X_k)  \right ) ^2 \right ]  \\
    &\ge -\mathbb{E}_{\mathbb{P}_1}\left [  \sum_{k=0}^K \pi_k(s,X) \cdot \underbrace{v(X_k)^2}_{\le \epsilon^2} \right ]  \\
    &\ge - \epsilon^2.
\end{align}
Then note that $g_0=g^*_c$ is a maximizer of $J_K$, so at $s=0$ we get vanishing first derivative:
\begin{align}
    J'(0) & = 0.
\end{align}
Then we consider the Taylor expansion around $s=0$ and get:
\begin{align}
  J_K(g) =  J(1) &= J(0) + \underbrace{J'(0)}_{=0} + \int_0^1 (1-u)\cdot \underbrace{J''(u)}_{\ge - \epsilon^2}\,du \\ & \ge J(0) - \epsilon^2 \cdot \int_0^1 (1-u)\,du \\
    & = J(0) - \frac{1}{2}\epsilon^2 \\
    & = J_K(g_c^*) - \frac{1}{2}\epsilon^2,
\end{align}
implying the inequality:
\begin{align}
   J_K(g) & \ge J_K(g_c^*) - \frac{1}{2}\epsilon^2, \qquad \text{ whenever }\qquad \|g-g^*_c\|_\infty \le \epsilon.
\end{align}
By the approximation assumption \ref{it:approx-class} we thus get the inequalities :
\begin{align}
 \operatorname{KL}(P_1\|P_0) \ge J_K(g_c^*) \ge   \sup_{\theta \in \Theta} J_K(g_\theta)  & \ge J_K(g_c^*) - \frac{1}{2}\epsilon^2.
\end{align}

h.) Finally, if we assume $\chi^2(P_1\|P_0) < \infty$, then a simple Jensen inequality shows:
\begin{align}
    J_K(g_c^*) &= \mathbb{E}_{\mathbb{P}_1}\left [  \log \left (  
    \frac{ \frac{dP_1}{dP_0}(Z^1)}{\frac{1}{K+1}\left (  \frac{dP_1}{dP_0}(Z^1) + \sum_{k=1}^K \frac{dP_1}{dP_0}(Z^0_k)\right ) } \right ) \right ]  \\
    &= \operatorname{KL}(P_1\|P_0) - \mathbb{E}_{\mathbb{P}_1}\left [  \log \left (  
    \frac{1}{K+1}\left (  \frac{dP_1}{dP_0}(Z^1) + \sum_{k=1}^K \frac{dP_1}{dP_0}(Z^0_k)\right ) \right ) \right ]  \\
    &\ge \operatorname{KL}(P_1\|P_0) - \log \mathbb{E}_{\mathbb{P}_1}\left [   
    \frac{1}{K+1}\left (  \frac{dP_1}{dP_0}(Z^1) + \sum_{k=1}^K \frac{dP_1}{dP_0}(Z^0_k)\right ) \right ]  \\
    &= \operatorname{KL}(P_1\|P_0) - \log \left (   
    \frac{1}{K+1}\left (  \mathbb{E}_{P_1}\left [  \frac{dP_1}{dP_0}(Z^1) \right ]  + \sum_{k=1}^K \mathbb{E}_{P_0}\left [  \frac{dP_1}{dP_0}(Z^0_k) \right ] \right )  \right )  \\
    &= \operatorname{KL}(P_1\|P_0) - \log \left (   
    \frac{1}{K+1}\left (  1 +\chi^2(P_1\|P_0) + \sum_{k=1}^K 1\right )  \right )  \\
    &= \operatorname{KL}(P_1\|P_0) - \log \left (   
    1 +\frac{\chi^2(P_1\|P_0)}{K+1} \right ) .
\end{align}
With this all claims are shown in \Cref{thm:approx-gro}.
